/* ═══════════════════════════════════════════════════════════
   MKL-45 INTERCEPTOR UI SYSTEM — Design Token Registry
   MIL-STD-810H // Hardened Transceiver Interface REV 8.4
   ═══════════════════════════════════════════════════════════ */

/* ─── LIGHT THEME (Default — Sand Canvas Deployment) ─── */
:root {
  /* Surfaces */
  --mkl-bg: #D8CCB6;
  --mkl-surface: #141312;
  --mkl-surface-low: #1C1B1A;
  --mkl-surface-mid: #252422;
  --mkl-surface-high: #32302D;
  --mkl-surface-bright: #3A3937;

  /* Steel Alloys */
  --mkl-steel-1: #A09F9A;
  --mkl-steel-2: #76756F;
  --mkl-steel-edge: #B5B4AE;
  --mkl-steel-base: #8A8984;

  /* Primary Accent — Cerakote Rust Orange */
  --mkl-acc: #D9712F;
  --mkl-acc-light: #FF9D5C;
  --mkl-acc-dark: #8E4417;

  /* Hazard Amber — LEDs, Warnings, Telemetry Only */
  --mkl-amb: #F2B01E;
  --mkl-amb-dim: #42310B;

  /* Danger — Emergency / Destructive */
  --mkl-danger: #D32F2F;
  --mkl-danger-light: #FF6B6B;
  --mkl-danger-dark: #7F1D1D;

  /* Success — Lock / Secure */
  --mkl-emerald: #2E7D32;
  --mkl-emerald-light: #00E676;
  --mkl-emerald-dim: #0F381E;

  /* Telemetry Cyan */
  --mkl-cyan: #0288D1;

  /* LCD / Amber Phosphor Display */
  --mkl-lcd: #150E00;
  --mkl-lcd-ink: #FFB000;
  --mkl-lcd-ghost: #281B00;
  --mkl-lcd-glow: 0 0 6px rgba(255, 176, 0, 0.65), 0 0 12px rgba(255, 176, 0, 0.3);
  --mkl-lcd-scanline: repeating-linear-gradient(
    0deg,
    rgba(0, 0, 0, 0.3) 0px,
    rgba(0, 0, 0, 0.3) 1px,
    transparent 1px,
    transparent 2px
  );

  /* Keycap Materials */
  --mkl-key: #D9D7D0;
  --mkl-key-shadow: #98968F;
  --mkl-key-dark: #232220;
  --mkl-key-dark-shadow: #11100F;

  /* On-surface text */
  --mkl-on-surface: #E6E2DE;
  --mkl-on-surface-variant: #DCC1B4;
  --mkl-outline: #A48C80;
  --mkl-outline-variant: #564339;

  /* Chamfer / Corner Cut */
  --mkl-cut-sm: 8px;
  --mkl-cut: 16px;
  --mkl-cut-lg: 24px;
  --mkl-fillet: 4px;

  /* Elevation Shadows */
  --mkl-shadow-recessed: inset 0 3px 8px rgba(0, 0, 0, 0.7), inset 0 1px 2px rgba(0, 0, 0, 0.9);
  --mkl-shadow-flush: 0 1px 3px rgba(0, 0, 0, 0.35);
  --mkl-shadow-plate: 0 4px 12px rgba(0, 0, 0, 0.45), 0 1px 3px rgba(0, 0, 0, 0.3);
  --mkl-shadow-switchgear: 0 8px 24px rgba(0, 0, 0, 0.55), 0 2px 6px rgba(0, 0, 0, 0.4);
  --mkl-shadow-keycap-pbt: 0 4px 0 #98968F, 0 6px 12px rgba(0, 0, 0, 0.45);
  --mkl-shadow-keycap-charcoal: 0 4px 0 #11100F, 0 6px 12px rgba(0, 0, 0, 0.65);
  --mkl-shadow-keycap-orange: 0 4px 0 #8E4417, 0 6px 12px rgba(217, 113, 47, 0.35);
  --mkl-shadow-keycap-red: 0 4px 0 #7F1D1D, 0 6px 12px rgba(211, 47, 47, 0.4);
  --mkl-shadow-keycap-active: 0 1px 0 rgba(0, 0, 0, 0.8), inset 0 2px 4px rgba(0, 0, 0, 0.5);

  /* Motion / Actuation Timings */
  --mkl-tp: 80ms;
  --mkl-ts: 300ms;
  --mkl-ease-actuation: cubic-bezier(0.2, 0, 0, 1);
  --mkl-ease-settle: cubic-bezier(0.34, 1.56, 0.64, 1);
  --mkl-lcd-step: steps(8, end);

  /* Spacing Scale (4px base) */
  --mkl-space-1: 4px;
  --mkl-space-2: 8px;
  --mkl-space-3: 12px;
  --mkl-space-4: 16px;
  --mkl-space-5: 20px;
  --mkl-space-6: 24px;
  --mkl-space-8: 32px;
  --mkl-space-10: 40px;
}

/* ─── DARK THEME (Night Vision Deployment) ─── */
[data-theme="dark"] {
  --mkl-bg: #0A0908;
  --mkl-surface: #0E0D0C;
  --mkl-surface-low: #141312;
  --mkl-surface-mid: #1C1B1A;
  --mkl-surface-high: #252422;
  --mkl-surface-bright: #32302D;

  --mkl-steel-1: #6B6A66;
  --mkl-steel-2: #4A4945;
  --mkl-steel-edge: #7A7975;
  --mkl-steel-base: #5C5B57;

  --mkl-acc: #C4652A;
  --mkl-acc-light: #E88A4F;
  --mkl-acc-dark: #7A3A15;

  --mkl-key: #3A3937;
  --mkl-key-shadow: #1A1918;
  --mkl-key-dark: #1A1918;
  --mkl-key-dark-shadow: #0A0908;

  --mkl-on-surface: #C4C0BC;
  --mkl-on-surface-variant: #A89080;

  --mkl-lcd-glow: 0 0 8px rgba(255, 176, 0, 0.85), 0 0 16px rgba(255, 176, 0, 0.4);

  --mkl-shadow-keycap-pbt: 0 4px 0 #1A1918, 0 6px 12px rgba(0, 0, 0, 0.65);
  --mkl-shadow-keycap-charcoal: 0 4px 0 #0A0908, 0 6px 12px rgba(0, 0, 0, 0.8);
}

/* ─── UTILITY CLASSES ─── */

/* 45° Chamfered Corners */
.chamfer-sm {
  clip-path: polygon(
    var(--mkl-cut-sm) 0%, calc(100% - var(--mkl-cut-sm)) 0%,
    100% var(--mkl-cut-sm), 100% calc(100% - var(--mkl-cut-sm)),
    calc(100% - var(--mkl-cut-sm)) 100%, var(--mkl-cut-sm) 100%,
    0% calc(100% - var(--mkl-cut-sm)), 0% var(--mkl-cut-sm)
  );
}

.chamfer {
  clip-path: polygon(
    var(--mkl-cut) 0%, calc(100% - var(--mkl-cut)) 0%,
    100% var(--mkl-cut), 100% calc(100% - var(--mkl-cut)),
    calc(100% - var(--mkl-cut)) 100%, var(--mkl-cut) 100%,
    0% calc(100% - var(--mkl-cut)), 0% var(--mkl-cut)
  );
}

.chamfer-lg {
  clip-path: polygon(
    var(--mkl-cut-lg) 0%, calc(100% - var(--mkl-cut-lg)) 0%,
    100% var(--mkl-cut-lg), 100% calc(100% - var(--mkl-cut-lg)),
    calc(100% - var(--mkl-cut-lg)) 100%, var(--mkl-cut-lg) 100%,
    0% calc(100% - var(--mkl-cut-lg)), 0% var(--mkl-cut-lg)
  );
}

/* Hazard Stripes */
.hazard-stripes {
  background: repeating-linear-gradient(
    -45deg,
    var(--mkl-amb) 0,
    var(--mkl-amb) 10px,
    var(--mkl-surface) 10px,
    var(--mkl-surface) 20px
  );
}

.hazard-stripes-danger {
  background: repeating-linear-gradient(
    -45deg,
    var(--mkl-danger) 0,
    var(--mkl-danger) 10px,
    var(--mkl-surface) 10px,
    var(--mkl-surface) 20px
  );
}

/* LCD Screen Base */
.lcd-screen {
  background-color: var(--mkl-lcd);
  background-image: var(--mkl-lcd-scanline);
  box-shadow: var(--mkl-shadow-recessed);
  color: var(--mkl-lcd-ink);
}

/* Phosphor Glow Text */
.lcd-glow {
  text-shadow: var(--mkl-lcd-glow);
}

/* Reduced Motion */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/registry/mkl45/lib/utils";

export const buttonVariants = cva(
  [
    "relative inline-flex items-center justify-center select-none font-sans tracking-wider uppercase font-bold",
    "transition-all duration-80 ease-[cubic-bezier(0.2,0,0,1)]",
    "focus:outline-none focus-visible:ring-2 focus-visible:ring-[var(--mkl-amb)] focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--mkl-surface)]",
    "disabled:pointer-events-none disabled:opacity-40 disabled:grayscale",
    "active:translate-y-[3px]",
  ],
  {
    variants: {
      variant: {
        // 01 Off-white PBT Keycap (Default)
        default: [
          "bg-[var(--mkl-key)] text-[var(--mkl-surface)] font-black",
          "border-t border-l border-white/60 border-r border-b border-[var(--mkl-key-shadow)]",
          "shadow-[0_4px_0_var(--mkl-key-shadow),0_6px_12px_rgba(0,0,0,0.45)] hover:brightness-105",
          "active:shadow-[0_1px_0_rgba(0,0,0,0.8),inset_0_2px_4px_rgba(0,0,0,0.5)]",
        ],
        // 02 Charcoal Tactical Keycap
        secondary: [
          "bg-[var(--mkl-key-dark)] text-[var(--mkl-steel-1)] font-bold",
          "border-t border-l border-[#3E3C38] border-r border-b border-black",
          "shadow-[0_4px_0_var(--mkl-key-dark-shadow),0_6px_12px_rgba(0,0,0,0.65)] hover:text-white hover:brightness-110",
          "active:shadow-[0_1px_0_rgba(0,0,0,0.8),inset_0_2px_4px_rgba(0,0,0,0.5)]",
        ],
        // 03 Cerakote Rust Orange (Primary Command)
        primary: [
          "bg-[var(--mkl-acc)] text-white font-extrabold",
          "border-t border-l border-[var(--mkl-acc-light)] border-r border-b border-[var(--mkl-acc-dark)]",
          "shadow-[0_4px_0_var(--mkl-acc-dark),0_6px_12px_rgba(217,113,47,0.35)] hover:brightness-110",
          "active:shadow-[0_1px_0_rgba(0,0,0,0.8),inset_0_2px_4px_rgba(0,0,0,0.5)]",
        ],
        // 04 Zero-Purge Emergency Red
        destructive: [
          "bg-[var(--mkl-danger)] text-white font-black",
          "border-t border-l border-[var(--mkl-danger-light)] border-r border-b border-[var(--mkl-danger-dark)]",
          "shadow-[0_4px_0_var(--mkl-danger-dark),0_6px_12px_rgba(211,47,47,0.4)] hover:brightness-110",
          "active:shadow-[0_1px_0_rgba(0,0,0,0.8),inset_0_2px_4px_rgba(0,0,0,0.5)]",
        ],
        // 05 Recessed Tray Bezel (Flush Key)
        outline: [
          "bg-[var(--mkl-surface-low)] text-[var(--mkl-amb)] font-mono font-medium",
          "border border-[var(--mkl-surface-mid)] shadow-[inset_0_3px_8px_rgba(0,0,0,0.8),inset_0_1px_2px_rgba(0,0,0,0.95)]",
          "hover:bg-[var(--mkl-surface-mid)]",
          "active:translate-y-0 active:bg-[var(--mkl-surface-high)]",
        ],
        // 06 Tactical Stencil Ghost
        ghost: [
          "bg-transparent text-[var(--mkl-steel-1)] border border-[var(--mkl-steel-2)]/40",
          "hover:bg-[var(--mkl-surface-high)]/40 hover:text-white",
          "active:translate-y-[1px]",
        ],
        // 07 Link / Reticle Link
        link: [
          "bg-transparent text-[var(--mkl-acc)] underline-offset-4 hover:underline font-mono lowercase tracking-normal",
          "active:translate-y-0",
        ],
      },
      size: {
        sm: "h-8 px-2.5 text-xs rounded-[3px] gap-1.5",
        default: "h-11 px-4 text-sm rounded-[4px] gap-2",
        lg: "h-14 px-6 text-base rounded-[6px] gap-3 tracking-widest",
        icon: "h-11 w-11 p-0 rounded-[4px]",
      },
      isLatched: {
        true: "translate-y-[3px] shadow-[0_1px_0_rgba(0,0,0,0.8),inset_0_2px_4px_rgba(0,0,0,0.5)] ring-1 ring-[var(--mkl-amb)]/60",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
      isLatched: false,
    },
  }
);

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof buttonVariants> {
  sublabel?: string;
  hasLed?: boolean;
  isLedActive?: boolean;
  ledColor?: "amber" | "emerald" | "red";
  isLoading?: boolean;
}

export const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  (
    {
      className,
      variant,
      size,
      sublabel,
      hasLed = false,
      isLedActive = false,
      ledColor = "amber",
      isLatched = false,
      isLoading = false,
      children,
      disabled,
      ...props
    },
    ref
  ) => {
    const ledColorClasses = {
      amber: isLedActive
        ? "bg-[var(--mkl-amb)] shadow-[0_0_8px_#F2B01E,0_0_2px_#FFF]"
        : "bg-[var(--mkl-amb-dim)]",
      emerald: isLedActive
        ? "bg-[var(--mkl-emerald-light)] shadow-[0_0_8px_#00E676,0_0_2px_#FFF]"
        : "bg-[var(--mkl-emerald-dim)]",
      red: isLedActive
        ? "bg-[#FF1744] shadow-[0_0_8px_#FF1744,0_0_2px_#FFF]"
        : "bg-[#400E0E]",
    };

    return (
      <button
        ref={ref}
        disabled={disabled || isLoading}
        className={cn(buttonVariants({ variant, size, isLatched, className }))}
        {...props}
      >
        {/* Concave keycap top glare overlay */}
        {variant !== "link" && variant !== "ghost" && (
          <span
            className="pointer-events-none absolute inset-x-1 top-0.5 h-1/3 rounded-t-sm bg-gradient-to-b from-white/20 to-transparent"
            aria-hidden="true"
          />
        )}

        {/* Optional Bi-Stable Status LED Jewel */}
        {hasLed && (
          <span
            className={cn(
              "absolute top-1.5 right-1.5 h-2 w-2 rounded-full border border-black/80 transition-colors duration-200",
              ledColorClasses[ledColor]
            )}
            aria-hidden="true"
          />
        )}

        {/* Loading Spinner */}
        {isLoading ? (
          <span className="flex items-center gap-2">
            <svg
              className="h-4 w-4 animate-spin text-current"
              xmlns="http://www.w3.org/2000/svg"
              fill="none"
              viewBox="0 0 24 24"
            >
              <circle
                className="opacity-25"
                cx="12"
                cy="12"
                r="10"
                stroke="currentColor"
                strokeWidth="4"
              />
              <path
                className="opacity-75"
                fill="currentColor"
                d="M4 12a8 8 0 018-8v8H4z"
              />
            </svg>
            <span className="font-mono text-xs">BUSY</span>
          </span>
        ) : (
          <span className="flex flex-col items-center justify-center leading-none">
            {children}
            {sublabel && (
              <span className="mt-1 font-mono text-[9px] font-normal opacity-70 tracking-normal">
                {sublabel}
              </span>
            )}
          </span>
        )}
      </button>
    );
  }
);

Button.displayName = "Button";

import * as React from "react";
import { cn } from "@/registry/mkl45/lib/utils";

export interface KbdProps extends React.HTMLAttributes<HTMLElement> {}

export const Kbd = React.forwardRef<HTMLElement, KbdProps>(
  ({ className, children, ...props }, ref) => {
    return (
      <kbd
        ref={ref}
        className={cn(
          "inline-flex items-center justify-center h-5 min-w-[20px] px-1.5 text-[10px] font-mono font-bold uppercase rounded-[2px]",
          "bg-[var(--mkl-key-dark)] text-[var(--mkl-key)] border-t border-l border-[var(--mkl-surface-high)] border-r border-b border-black",
          "shadow-[0_2px_0_#0F0E0C] select-none",
          className
        )}
        {...props}
      >
        {children}
      </kbd>
    );
  }
);

Kbd.displayName = "Kbd";

import * as React from "react";
import { cn } from "@/registry/mkl45/lib/utils";

export interface HexScrewProps extends React.HTMLAttributes<HTMLDivElement> {
  size?: "sm" | "default" | "lg";
}

export const HexScrew: React.FC<HexScrewProps> = ({
  className,
  size = "default",
  ...props
}) => {
  const sizeClasses = {
    sm: "w-2.5 h-2.5",
    default: "w-3 h-3",
    lg: "w-4 h-4",
  };

  const innerSize = {
    sm: "w-1 h-1",
    default: "w-1.5 h-1.5",
    lg: "w-2 h-2",
  };

  return (
    <div
      className={cn(
        "rounded-full bg-[var(--mkl-surface-bright)] flex items-center justify-center shadow-[inset_0_1px_2px_#000,0_1px_1px_rgba(255,255,255,0.15)]",
        sizeClasses[size],
        className
      )}
      aria-hidden="true"
      {...props}
    >
      <div
        className={cn(
          "bg-[var(--mkl-surface-low)] rotate-45 border-[0.5px] border-black/60",
          innerSize[size]
        )}
      />
    </div>
  );
};

export interface ChassisPlateProps extends React.HTMLAttributes<HTMLDivElement> {
  title?: string;
  serial?: string;
  spec?: string;
  hasScrews?: boolean;
  chamfer?: "none" | "sm" | "default" | "lg";
}

export const ChassisPlate = React.forwardRef<HTMLDivElement, ChassisPlateProps>(
  (
    {
      className,
      title,
      serial,
      spec,
      hasScrews = true,
      chamfer = "none",
      children,
      ...props
    },
    ref
  ) => {
    const chamferClass =
      chamfer === "sm"
        ? "chamfer-sm"
        : chamfer === "default"
        ? "chamfer"
        : chamfer === "lg"
        ? "chamfer-lg"
        : "rounded-lg";

    return (
      <div
        ref={ref}
        className={cn(
          "relative bg-[var(--mkl-surface)] border border-[var(--mkl-surface-high)] shadow-[0_12px_28px_rgba(0,0,0,0.45),inset_0_1px_0_rgba(255,255,255,0.08)] p-5",
          chamferClass,
          className
        )}
        {...props}
      >
        {hasScrews && (
          <>
            <HexScrew className="absolute top-2.5 left-2.5" />
            <HexScrew className="absolute top-2.5 right-2.5" />
            <HexScrew className="absolute bottom-2.5 left-2.5" />
            <HexScrew className="absolute bottom-2.5 right-2.5" />
          </>
        )}

        {(title || serial || spec) && (
          <div className="flex flex-wrap items-center justify-between gap-2 pb-3 mb-4 border-b border-[var(--mkl-surface-mid)] font-mono text-xs">
            <div className="flex items-center gap-2">
              <span className="w-2 h-2 rounded-full bg-[var(--mkl-amb)] shadow-[0_0_6px_var(--mkl-amb)]" />
              {title && (
                <span className="font-bold uppercase tracking-wider text-[var(--mkl-on-surface)]">
                  {title}
                </span>
              )}
              {spec && (
                <span className="text-[var(--mkl-on-surface-variant)] opacity-75">
                  // {spec}
                </span>
              )}
            </div>
            {serial && (
              <span className="px-2 py-0.5 rounded bg-[var(--mkl-surface-low)] text-[var(--mkl-amb)] shadow-[inset_0_1px_2px_#000] text-[10px]">
                [{serial}]
              </span>
            )}
          </div>
        )}

        {children}
      </div>
    );
  }
);

ChassisPlate.displayName = "ChassisPlate";

import * as React from "react";
import { cn } from "@/registry/mkl45/lib/utils";

export interface LCDScreenProps extends React.HTMLAttributes<HTMLDivElement> {
  scanlines?: boolean;
  glow?: boolean;
}

export const LCDScreen = React.forwardRef<HTMLDivElement, LCDScreenProps>(
  ({ className, scanlines = true, glow = true, children, ...props }, ref) => {
    return (
      <div
        ref={ref}
        className={cn(
          "relative bg-[var(--mkl-lcd)] text-[var(--mkl-lcd-ink)] font-mono p-3 rounded border border-black/80",
          "shadow-[inset_0_3px_8px_rgba(0,0,0,0.9),inset_0_1px_2px_#000]",
          scanlines && "lcd-screen",
          glow && "lcd-glow",
          className
        )}
        {...props}
      >
        {children}
      </div>
    );
  }
);

LCDScreen.displayName = "LCDScreen";

import * as React from "react";
import { cn } from "@/registry/mkl45/lib/utils";

export interface InputProps
  extends React.InputHTMLAttributes<HTMLInputElement> {
  error?: boolean;
}

export const Input = React.forwardRef<HTMLInputElement, InputProps>(
  ({ className, type, error, ...props }, ref) => {
    return (
      <div className="relative w-full">
        <input
          type={type}
          ref={ref}
          className={cn(
            "w-full h-11 px-3.5 rounded-[3px] font-mono text-xs text-[var(--mkl-lcd-ink)] select-text",
            "bg-[var(--mkl-lcd)] border border-black/80 shadow-[inset_0_3px_8px_rgba(0,0,0,0.9),inset_0_1px_2px_#000]",
            "placeholder:text-[var(--mkl-lcd-ghost)] placeholder:font-mono",
            "focus:outline-none focus:border-[var(--mkl-amb)] focus:ring-1 focus:ring-[var(--mkl-amb)] focus:shadow-[inset_0_2px_6px_#000,0_0_8px_rgba(242,176,30,0.3)]",
            "disabled:opacity-40 disabled:cursor-not-allowed",
            "transition-all duration-80",
            error &&
              "border-[var(--mkl-danger)] text-[var(--mkl-danger-light)] focus:border-[var(--mkl-danger)] focus:ring-[var(--mkl-danger)] focus:shadow-[0_0_8px_rgba(211,47,47,0.4)]",
            className
          )}
          {...props}
        />
        {/* Subtle scanline overlay */}
        <span
          className="pointer-events-none absolute inset-0 rounded-[3px] opacity-40 bg-[repeating-linear-gradient(0deg,rgba(0,0,0,0.4)_0px,rgba(0,0,0,0.4)_1px,transparent_1px,transparent_2px)]"
          aria-hidden="true"
        />
      </div>
    );
  }
);

Input.displayName = "Input";

import * as React from "react";
import { cn } from "@/registry/mkl45/lib/utils";

export interface TextareaProps
  extends React.TextareaHTMLAttributes<HTMLTextAreaElement> {
